contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint _value, bool _isOwner) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= _value, "insufficient test balance");
        require(c.owner() == address(this), "test must be owner");

        uint balBefore = address(c).balance;
        uint thisBefore = address(this).balance;

        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;
        uint thisAfter = address(this).balance;

        assert(
            (balBefore >= _value && !reverted && balAfter == balBefore - _value && thisAfter == thisBefore + _value) ||
            (balBefore < _value && reverted && balAfter == balBefore && thisAfter == thisBefore)
        );
    }
}

