// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _value, bool _isOwner) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _value);
        vm.assume(c.owner() == address(this));
        uint balBefore = address(c).balance;
        uint thisBefore = address(this).balance;
        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        uint thisAfter = address(this).balance;
        assertTrue((balBefore >= _value && !reverted && balAfter == balBefore - _value && thisAfter == thisBefore + _value) ||
            (balBefore < _value && reverted && balAfter == balBefore && thisAfter == thisBefore));
    }

    function testFuzz_run(uint256 _value, bool _isOwner) public {
        _run(_value, _isOwner);
    }

    receive() external payable {}
}
